mapper.select:
SELECT t1.id, t1.rule_name, t1.vendor_config_id, t2.vendor_name, t2.vendor_code, t1.model_name, t1.input_price, t1.output_price, t1.price_unit, t1.currency, t1.billing_type, t1.status, t1.sort, t1.remark, t1.create_time FROM sys_llm_billing_rule t1 LEFT JOIN sys_llm_vendor_config t2 ON t1.vendor_config_id = t2.id AND t2.is_deleted = 0
t1.is_deleted = 0
AND ( t1.rule_name LIKE '%' || #{queryParams.keywords} || '%' OR t1.model_name LIKE '%' || #{queryParams.keywords} || '%' )
AND t1.vendor_config_id = #{queryParams.vendorConfigId}
AND t1.status = #{queryParams.status}
ORDER BY t1.sort, t1.create_time DESC
